examples.fixed_code:
func processItems(items []string) {
    results := make(chan string, len(items)) // Buffered channel

    for _, item := range items {
        go func(i string) {
            results <- process(i)
        }(item)
    }

    // Read first result
    firstResult := <-results
    fmt.Println(firstResult)

    // Drain remaining results to unblock goroutines
    go func() {
        for i := 1; i < len(items); i++ {
            <-results
        }
    }()
}

