# Use enum and dict for extensibility
from enum import Enum

class CustomerType(Enum):
    REGULAR = 1
    PREMIUM = 2
    VIP = 3

DISCOUNTS = {
    CustomerType.REGULAR: 0.0,
    CustomerType.PREMIUM: 0.10,
    CustomerType.VIP: 0.25
}

def calculate_price(base_price, customer_type):
    discount = DISCOUNTS.get(customer_type, 0.0)
    return base_price * (1 - discount)

