def generate_report(data):
    html_parts = [
        generate_header(),
        generate_table(data),
        generate_footer(data)
    ]
    return wrap_in_html(''.join(html_parts))

def generate_header():
    return "<h1>Sales Report</h1>"

def generate_table(data):
    rows = [generate_table_row(item) for item in data]
    return f"<table><tr><th>Item</th><th>Sales</th></tr>{''.join(rows)}</table>"

def generate_table_row(item):
    return f"<tr><td>{item['name']}</td><td>${item['sales']}</td></tr>"

def generate_footer(data):
    total = sum(item['sales'] for item in data)
    return f"<p>Total: ${total}</p>"

def wrap_in_html(content):
    return f"<html><body>{content}</body></html>"
